UPDATE pagamento AS pg
SET status_pagamento = 'PAGO',
    data_pagamento   = (a.data_agendamento + TIME '18:30') AT TIME ZONE 'America/Fortaleza'
FROM agendamento AS a
WHERE a.id_agendamento = pg.id_agendamento
  AND pg.id_pagamento IN (
                          'b0000000-0000-0000-0000-000000000001',
                          'b0000000-0000-0000-0000-000000000002',
                          'b0000000-0000-0000-0000-000000000003',
                          'b0000000-0000-0000-0000-000000000004',
                          'b0000000-0000-0000-0000-000000000005',
                          'b0000000-0000-0000-0000-000000000006',
                          'b0000000-0000-0000-0000-000000000007',
                          'b0000000-0000-0000-0000-000000000008',
                          'b0000000-0000-0000-0000-000000000010',
                          'b0000000-0000-0000-0000-000000000011',
                          'b0000000-0000-0000-0000-000000000012',
                          'b0000000-0000-0000-0000-000000000014',
                          'b0000000-0000-0000-0000-000000000015',
                          'b0000000-0000-0000-0000-000000000017');

UPDATE pagamento
SET status_pagamento = 'ATRASADO'
WHERE status_pagamento = 'PENDENTE'
  AND id_agendamento IN (SELECT id_agendamento
                         FROM agendamento
                         WHERE data_agendamento < DATE '2026-10-20');

UPDATE vinculo_psicologo_paciente
SET data_fim            = DATE '2026-08-31',
    motivo_encerramento = 'Alta terapêutica'
WHERE id_vinculo = '90000000-0000-0000-0000-000000000009';

UPDATE vinculo_psicologo_paciente
SET data_fim            = DATE '2026-07-15',
    motivo_encerramento = 'Mudança de cidade do paciente'
WHERE id_vinculo = '90000000-0000-0000-0000-000000000011';

UPDATE prontuario
SET status = 'ENCERRADO'
WHERE id_paciente IN ('60000000-0000-0000-0000-000000000008', '60000000-0000-0000-0000-000000000010');

UPDATE paciente
SET telefone = '(88) 99999-0014'
WHERE id_paciente = '60000000-0000-0000-0000-000000000014';

COMMIT;

-- ============================================================================
-- consultas uteis do sistema (item 'c' do edital do professor)
-- criamos 8 consultas relacionais para cobrir todas as clausulas obrigatorias:
-- funcoes agregadas, subqueries aninhadas, inner/left joins, group by, having e in.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- consulta 1: faturamento e sessoes concluidas por psicologo
-- mostra o total de consultas, sessoes concluidas, valor recebido e a receber por profissional.
-- clausulas: inner join, left join, count, sum com filter, group by, having e in.
-- ----------------------------------------------------------------------------
SELECT u.nome                                                                            AS psicologo,
       ps.numero_crp,
       COUNT(a.id_agendamento)                                                           AS total_agendamentos,
       COUNT(*) FILTER (WHERE a.status_agendamento = 'CONCLUIDO')                        AS sessoes_concluidas,
       COALESCE(SUM(a.valor_cobrado)
                FILTER (WHERE pg.status_pagamento = 'PAGO'), 0)                          AS receita_recebida,
       COALESCE(SUM(a.valor_cobrado)
                FILTER (WHERE pg.status_pagamento IN ('PENDENTE', 'ATRASADO')), 0)       AS receita_a_receber
FROM psicologo ps
         JOIN usuario u ON u.id_usuario = ps.id_usuario
         JOIN vinculo_especialidade_psicologo vep ON vep.id_psicologo = ps.id_usuario
         JOIN agendamento a ON a.id_vinculo_especialidade = vep.id_vinculo_especialidade
         LEFT JOIN pagamento pg ON pg.id_agendamento = a.id_agendamento
WHERE a.status_agendamento <> 'CANCELADO'
GROUP BY u.nome, ps.numero_crp
HAVING COUNT(a.id_agendamento) >= 2
ORDER BY receita_recebida DESC;

-- ----------------------------------------------------------------------------
-- consulta 2: pacientes sem prontuario aberto (anti-join com left join)
-- identifica pacientes que foram cadastrados mas ainda nao possuem ficha de prontuario aberta.
-- clausulas: inner join, left join e where ... is null.
-- ----------------------------------------------------------------------------
SELECT p.nome,
       p.telefone,
       p.esta_ativo,
       e.municipio
FROM paciente p
         JOIN endereco e ON e.id_endereco = p.id_endereco
         LEFT JOIN prontuario pr ON pr.id_paciente = p.id_paciente
WHERE pr.id_prontuario IS NULL
ORDER BY p.nome;

-- ----------------------------------------------------------------------------
-- consulta 3: sessoes realizadas pendentes de evolucao clinica
-- alerta para a gestao da clinica: sessoes onde o paciente esteve presente
-- mas o psicologo ainda nao digitou o texto da evolucao medica obrigatoria.
-- clausulas: multiplos inner joins e left join com evolucao_psicologica.
-- ----------------------------------------------------------------------------
SELECT up.nome            AS psicologo,
       pac.nome           AS paciente,
       a.data_agendamento AS data_sessao,
       s.inicio_real
FROM sessao_atendimento s
         JOIN agendamento a ON a.id_agendamento = s.id_agendamento
         JOIN paciente pac ON pac.id_paciente = a.id_paciente
         JOIN vinculo_especialidade_psicologo vep ON vep.id_vinculo_especialidade = a.id_vinculo_especialidade
         JOIN usuario up ON up.id_usuario = vep.id_psicologo
         LEFT JOIN evolucao_psicologica ev ON ev.id_sessao = s.id_sessao
WHERE s.status_presenca = 'PRESENTE'
  AND ev.id_evolucao IS NULL
ORDER BY a.data_agendamento, up.nome;

-- ----------------------------------------------------------------------------
-- consulta 4: taxa percentual de faltas de pacientes por profissional
-- calcula a porcentagem de ausencias dos pacientes nas sessoes de cada psicologo.
-- clausulas: inner join, count com filter, calculo percentual com round, group by e having.
-- ----------------------------------------------------------------------------
SELECT up.nome                                               AS psicologo,
       COUNT(*)                                              AS sessoes_registradas,
       COUNT(*) FILTER (WHERE s.status_presenca = 'AUSENTE') AS faltas,
       ROUND(100.0 * COUNT(*) FILTER (WHERE s.status_presenca = 'AUSENTE')
                 / COUNT(*), 1)                              AS percentual_faltas
FROM sessao_atendimento s
         JOIN agendamento a ON a.id_agendamento = s.id_agendamento
         JOIN vinculo_especialidade_psicologo vep ON vep.id_vinculo_especialidade = a.id_vinculo_especialidade
         JOIN usuario up ON up.id_usuario = vep.id_psicologo
GROUP BY up.nome
HAVING COUNT(*) >= 2
ORDER BY percentual_faltas DESC, sessoes_registradas DESC;

-- ----------------------------------------------------------------------------
-- consulta 5: pacientes com debito acima da media da clinica (subquery aninhada no having)
-- lista apenas os pacientes cuja divida pendente supera a divida media de todos os pacientes.
-- clausulas: inner join, group by e subquery aninhada dentro da clausula having.
-- ----------------------------------------------------------------------------
SELECT p.nome                  AS paciente,
       COUNT(*)                AS cobrancas_em_aberto,
       SUM(a.valor_cobrado)    AS total_devido,
       MIN(a.data_agendamento) AS sessao_mais_antiga
FROM paciente p
         JOIN agendamento a ON a.id_paciente = p.id_paciente
         JOIN pagamento pg ON pg.id_agendamento = a.id_agendamento
WHERE pg.status_pagamento IN ('PENDENTE', 'ATRASADO')
GROUP BY p.id_paciente, p.nome
HAVING SUM(a.valor_cobrado) > (SELECT AVG(divida.total)
                               FROM (SELECT SUM(a2.valor_cobrado) AS total
                                     FROM agendamento a2
                                              JOIN pagamento pg2 ON pg2.id_agendamento = a2.id_agendamento
                                     WHERE pg2.status_pagamento IN ('PENDENTE', 'ATRASADO')
                                     GROUP BY a2.id_paciente) AS divida)
ORDER BY total_devido DESC;

-- ----------------------------------------------------------------------------
-- consulta 6: psicologos por especialidades com subqueries aninhadas e operador in
-- lista os psicologos que atendem areas especificas (neuropsicologia ou psicologia infantil)
-- e concatena todas as especialidades dele em uma unica linha.
-- clausulas: inner join, subqueries aninhadas com in e agregacao string_agg.
-- ----------------------------------------------------------------------------
SELECT u.nome                                         AS psicologo,
       ps.numero_crp,
       (SELECT string_agg(e.nome, ', ' ORDER BY e.nome)
        FROM vinculo_especialidade_psicologo v
                 JOIN especialidade e ON e.id_especialidade = v.id_especialidade
        WHERE v.id_psicologo = ps.id_usuario)         AS especialidades
FROM psicologo ps
         JOIN usuario u ON u.id_usuario = ps.id_usuario
WHERE ps.id_usuario IN (SELECT vep.id_psicologo
                        FROM vinculo_especialidade_psicologo vep
                        WHERE vep.id_especialidade IN (SELECT id_especialidade
                                                       FROM especialidade
                                                       WHERE nome IN ('Neuropsicologia',
                                                                      'Psicologia Infantil')))
ORDER BY u.nome;

-- ----------------------------------------------------------------------------
-- consulta 7: ocupacao das janelas de atendimento da clinica
-- conta quantas sessoes foram realizadas, quantas estao agendadas e quantas foram canceladas por janela semanal.
-- clausulas: left join, count com filter e group by por dia e horario.
-- ----------------------------------------------------------------------------
SELECT u.nome                                                                    AS psicologo,
       d.dia_semana,
       d.janela_hora_inicio                                                      AS inicio,
       d.janela_hora_fim                                                         AS fim,
       COUNT(a.id_agendamento) FILTER (WHERE a.status_agendamento = 'CONCLUIDO') AS sessoes_realizadas,
       COUNT(a.id_agendamento) FILTER (WHERE a.status_agendamento = 'AGENDADO')  AS sessoes_futuras,
       COUNT(a.id_agendamento) FILTER (WHERE a.status_agendamento = 'CANCELADO') AS cancelamentos
FROM disponibilidade_agenda d
         JOIN usuario u ON u.id_usuario = d.id_psicologo
         LEFT JOIN agendamento a ON a.id_disponibilidade = d.id_disponibilidade
GROUP BY u.nome, d.dia_semana, d.janela_hora_inicio, d.janela_hora_fim
ORDER BY u.nome, d.dia_semana, d.janela_hora_inicio;

-- ----------------------------------------------------------------------------
-- consulta 8: menores de idade e seus responsaveis legais
-- filtra pacientes com menos de 18 anos e exibe a lista dos responsaveis e o parentesco.
-- clausulas: left joins, calculo de idade com extract e age(), string_agg e group by.
-- ----------------------------------------------------------------------------
SELECT p.nome                                                       AS paciente,
       EXTRACT(YEAR FROM age(CURRENT_DATE, p.data_nascimento))::int AS idade,
       COUNT(r.id_responsavel)                                      AS qtd_responsaveis,
       COALESCE(string_agg(r.nome || ' (' || vpr.parentesco::text || ')', '; '
                           ORDER BY vpr.parentesco),
                'SEM RESPONSÁVEL CADASTRADO')                       AS responsaveis
FROM paciente p
         LEFT JOIN vinculo_paciente_responsavel vpr ON vpr.id_paciente = p.id_paciente
         LEFT JOIN responsavel_legal r ON r.id_responsavel = vpr.id_responsavel
WHERE p.data_nascimento > CURRENT_DATE - INTERVAL '18 years'
GROUP BY p.id_paciente, p.nome, p.data_nascimento
ORDER BY idade, p.nome;